		return <div>{element}</div>;
	}

	render(<App count={0} />, scratch);
	render(<App count={1} />, scratch);
	render(<App count={2} />, scratch);
	expect(calls.length).to.equal(1);
	expect(calls[0]).to.equal(scratch.firstChild.firstChild);
});

